// Package upgrade brings projects generated by older GOT versions up to date.
//
// Steps detect their need from the project files rather than from a recorded
// version, so they also work for projects created before got-project.json
// existed. A step only rewrites code that still matches what GOT generated;
// when a developer has changed it, the step reports a manual action instead.
package upgrade

import (
	"bytes"
	"fmt"
	"go/format"
	"os"
	"path/filepath"
	"sort"
	"strings"

	"github.com/gotcli/got/internal/generator"
)

type Status string

const (
	StatusPending  Status = "pending"
	StatusUpToDate Status = "up-to-date"
	StatusManual   Status = "manual"
)

// Result describes one step for one project. Changes maps project-relative
// paths to their complete new content.
type Result struct {
	ID          string            `json:"id"`
	Description string            `json:"description"`
	Status      Status            `json:"status"`
	Detail      string            `json:"detail,omitempty"`
	Changes     map[string][]byte `json:"-"`
	Files       []string          `json:"files,omitempty"`
}

type step struct {
	id          string
	description string
	plan        func(project string, version string) (Status, string, map[string][]byte, error)
}

var steps = []step{
	{id: "gitignore-indentation", description: "make .gitignore patterns match (config.yml with secrets was not ignored)", plan: planGitignore},
	{id: "database-connect-error", description: "return database connection errors instead of panicking", plan: planConnectError},
	{id: "project-manifest", description: "record the project in " + generator.ProjectManifestName, plan: planManifest},
}

// Plan evaluates every step against the project without writing anything.
func Plan(project, version string) ([]Result, error) {
	results := make([]Result, 0, len(steps))
	for _, step := range steps {
		status, detail, changes, err := step.plan(project, version)
		if err != nil {
			return nil, fmt.Errorf("%s: %w", step.id, err)
		}
		result := Result{ID: step.id, Description: step.description, Status: status, Detail: detail, Changes: changes}
		for path := range changes {
			result.Files = append(result.Files, path)
		}
		sort.Strings(result.Files)
		results = append(results, result)
	}
	return results, nil
}

// Apply writes the changes of every pending result. Each file keeps its mode.
func Apply(project string, results []Result) error {
	for _, result := range results {
		if result.Status != StatusPending {
			continue
		}
		for _, path := range result.Files {
			fullPath := filepath.Join(project, path)
			mode := os.FileMode(0o644)
			if info, err := os.Stat(fullPath); err == nil {
				mode = info.Mode().Perm()
			}
			if err := os.WriteFile(fullPath, result.Changes[path], mode); err != nil {
				return fmt.Errorf("%s: write %s: %w", result.ID, path, err)
			}
		}
	}
	return nil
}

func planGitignore(project, _ string) (Status, string, map[string][]byte, error) {
	content, err := os.ReadFile(filepath.Join(project, ".gitignore"))
	if os.IsNotExist(err) {
		return StatusUpToDate, "no .gitignore", nil, nil
	}
	if err != nil {
		return "", "", nil, err
	}
	lines := strings.Split(string(content), "\n")
	changed := false
	for i, line := range lines {
		trimmed := strings.TrimLeft(line, " \t")
		if trimmed != line {
			lines[i] = trimmed
			changed = true
		}
	}
	if !changed {
		return StatusUpToDate, "", nil, nil
	}
	return StatusPending, "", map[string][]byte{".gitignore": []byte(strings.Join(lines, "\n"))}, nil
}

const (
	panickingSignature = "func ConnectDB() *gorm.DB {"
	panickingReturn    = "\tif err != nil {\n\t\tpanic(err)\n\t}\n\n\treturn conn\n}"
	panickingCall      = "\tconn := databases.ConnectDB()\n"
)

func planConnectError(project, _ string) (Status, string, map[string][]byte, error) {
	databaseFile, err := findDatabaseFile(project)
	if err != nil || databaseFile == "" {
		return StatusUpToDate, "no generated database connection found", nil, err
	}
	database, err := os.ReadFile(filepath.Join(project, databaseFile))
	if err != nil {
		return "", "", nil, err
	}
	if !bytes.Contains(database, []byte(panickingSignature)) {
		return StatusUpToDate, "", nil, nil
	}
	main, err := os.ReadFile(filepath.Join(project, "main.go"))
	if err != nil {
		return "", "", nil, err
	}
	manual := fmt.Sprintf("%s and main.go differ from the generated code; change ConnectDB to return (*gorm.DB, error) and handle the error in main with log.Fatalf", databaseFile)
	if bytes.Count(database, []byte(panickingReturn)) != 1 || bytes.Count(main, []byte(panickingCall)) != 1 {
		return StatusManual, manual, nil, nil
	}
	updatedDatabase := bytes.Replace(database, []byte(panickingSignature), []byte("// ConnectDB opens the database. The returned error never contains the password.\nfunc ConnectDB() (*gorm.DB, error) {"), 1)
	updatedDatabase = bytes.Replace(updatedDatabase, []byte(panickingReturn), []byte(`	if err != nil {
		return nil, fmt.Errorf("connect to database %s at %s:%d: %w",
			viper.GetString("DB_NAME"), viper.GetString("DB_HOST"), viper.GetInt("DB_PORT"), err)
	}

	return conn, nil
}`), 1)
	updatedMain := bytes.Replace(main, []byte(panickingCall), []byte("\tconn, err := databases.ConnectDB()\n\tif err != nil {\n\t\tlog.Fatalf(\"failed to start: %v\", err)\n\t}\n"), 1)
	// Both files must still parse; otherwise leave them for the developer.
	formattedDatabase, err := format.Source(updatedDatabase)
	if err != nil {
		return StatusManual, manual, nil, nil
	}
	formattedMain, err := format.Source(updatedMain)
	if err != nil {
		return StatusManual, manual, nil, nil
	}
	return StatusPending, "", map[string][]byte{databaseFile: formattedDatabase, "main.go": formattedMain}, nil
}

func findDatabaseFile(project string) (string, error) {
	for _, name := range []string{"pg.go", "mysql.go", "mssql.go"} {
		relative := filepath.Join("databases", name)
		if _, err := os.Stat(filepath.Join(project, relative)); err == nil {
			return relative, nil
		} else if !os.IsNotExist(err) {
			return "", err
		}
	}
	return "", nil
}

func planManifest(project, version string) (Status, string, map[string][]byte, error) {
	manifest, err := generator.ReadProjectManifest(project)
	missing := os.IsNotExist(err)
	if err != nil && !missing {
		return "", "", nil, err
	}
	if missing {
		if manifest, err = inferManifest(project); err != nil {
			return "", "", nil, err
		}
	}
	// Development builds have no meaningful version to record.
	recordVersion := version != "" && version != "dev" && manifest.GOTVersion != version
	if !missing && !recordVersion {
		return StatusUpToDate, "", nil, nil
	}
	detail := "create"
	if !missing {
		detail = fmt.Sprintf("gotVersion %q -> %q", manifest.GOTVersion, version)
	}
	if recordVersion {
		manifest.GOTVersion = version
	}
	encoded, err := generator.EncodeProjectManifest(manifest)
	if err != nil {
		return "", "", nil, err
	}
	return StatusPending, detail, map[string][]byte{generator.ProjectManifestName: encoded}, nil
}

func inferManifest(project string) (generator.ProjectManifest, error) {
	var manifest generator.ProjectManifest
	content, err := os.ReadFile(filepath.Join(project, "go.mod"))
	if err != nil {
		return manifest, fmt.Errorf("read go.mod: %w", err)
	}
	for _, line := range strings.Split(string(content), "\n") {
		if fields := strings.Fields(line); len(fields) == 2 && fields[0] == "module" {
			manifest.Module = fields[1]
		}
	}
	manifest.Architecture = "standard"
	if _, err := os.Stat(filepath.Join(project, "routes", "health.go")); err == nil {
		manifest.Architecture = "microservice"
	}
	if databaseFile, err := findDatabaseFile(project); err == nil && databaseFile != "" {
		manifest.Database = strings.TrimSuffix(filepath.Base(databaseFile), ".go")
	}
	return manifest, nil
}
